/// One `buildCivic` result. `apse`/`belfry` empty means the reference's
/// `null`; `hall` and `columns` are flat `[x, y, ...]`.
pub struct CivicG {
    pub style: &'static str,
    pub name: &'static str,
    pub dome: bool,
    pub center: (f64, f64),
    pub hall: &'static [f64],
    pub columns: &'static [f64],
    pub belfry: Option<(f64, f64)>,
    pub apse: Option<&'static [f64]>,
    pub prov: &'static str,
}

pub struct CivicCase {
    pub name: &'static str,
    pub pop: f64,
    pub style: &'static str,
    pub faith: &'static str,
    pub has_plaza: bool,
    /// `None` where the reference returned `null`.
    pub out: Option<CivicG>,
}

